# /etc/nftables.conf on the backup server (default-deny host firewall)
table inet backup {
  set agents  { type ipv4_addr; elements = { 192.0.2.20, 192.0.2.21 } }
  set jump    { type ipv4_addr; elements = { 198.51.100.5 } }

  chain input {
    type filter hook input priority 0; policy drop;
    ct state established,related accept
    iif lo accept
    ip saddr @agents tcp dport 443 accept          # backup traffic
    ip saddr @jump   tcp dport { 22, 443 } accept  # administration
    log prefix "backup-drop: " limit rate 5/minute
  }
  chain output {
    type filter hook output priority 0; policy drop;
    ct state established,related accept
    udp dport { 53, 123 } accept
    ip daddr 203.0.113.40 tcp dport 443 accept     # off-site vault gateway
  }
}

